#include <bits/stdc++.h>
using namespace std;

class mcf_graph_int_cost {
public:
    int n;
    std::vector<std::pair<int, int>> pos;
    std::vector<std::vector<struct _edge>> g;

    mcf_graph_int_cost(int n) : n(n), g(n) {}

    int add_edge(int from_, int to, int cap, int cost) {
        int m = (int)pos.size();
        pos.emplace_back(from_, (int)g[from_].size());
        g[from_].push_back(_edge(to, (int)g[to].size(), cap, 0, cost));
        g[to].push_back(_edge(from_, (int)g[from_].size() - 1, 0, 0, -cost));
        return m;
    }

    struct _edge {
        int to;
        int rev;
        long long cap;
        long long flow;
        long long cost;
        _edge(int to_, int rev_, long long cap_, long long flow_, long long cost_)
            : to(to_), rev(rev_), cap(cap_), flow(flow_), cost(cost_) {}
    };

    class edge {
    public:
        int from_;
        int to;
        long long cap;
        long long flow;
        long long cost;
        edge(int from_, int to, long long cap, long long flow, long long cost)
            : from_(from_), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    edge get_edge(int i) {
        auto &_e = g[pos[i].first][pos[i].second];
        auto &_re = g[_e.to][_e.rev];
        return edge(pos[i].first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost);
    }

    std::vector<edge> edges() {
        std::vector<edge> ret;
        for (int i = 0; i < (int)pos.size(); i++) {
            auto &_e = g[pos[i].first][pos[i].second];
            auto &_re = g[_e.to][_e.rev];
            ret.emplace_back(pos[i].first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost);
        }
        return ret;
    }

    bool _dual_ref(int s, int t) {
        std::vector<unsigned long long> dist(n, ULLONG_MAX);
        std::vector<int> pv(n, -1);
        std::vector<int> pe(n, -1);
        std::vector<bool> vis(n, false);
        typedef std::pair<unsigned long long, int> P; // (distance, node)
        std::priority_queue<P, std::vector<P>, std::greater<P>> que;

        dist[s] = 0;
        que.emplace(0, s);
        while (!que.empty()) {
            auto [d, v] = que.top(); que.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)g[v].size(); i++) {
                auto &e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                long long cost = e.cost - dual[e.to] + dual[v];
                unsigned long long nd = dist[v] + cost;
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    que.emplace(nd, e.to);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= long long(dist[t]) - long long(dist[v]);
            }
        }
        return true;
    }

    std::vector<std::pair<long long, long long>> slope(int s, int t, unsigned long long flow_limit = ULLONG_MAX) {
        dual.assign(n, 0);
        std::vector<unsigned long long> dist(n, ULLONG_MAX);
        std::vector<int> pv(n, -1);
        std::vector<int> pe(n, -1);
        std::vector<bool> vis(n, false);

        long long flow = 0;
        long long cost = 0;
        long long prev_cost = -1;
        std::vector<std::pair<long long, long long>> result;
        result.emplace_back(flow, cost);
        while (flow < (long long)flow_limit) {
            if (!_dual_ref(s, t)) break;
            unsigned long long c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = std::min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                auto &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            long long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                result.pop_back();
            }
            result.emplace_back(flow, cost);
            prev_cost = d;
        }
        return result;
    }

    long long flow(int s, int t, unsigned long long flow_limit=ULLONG_MAX) {
        auto res = slope(s,t,flow_limit);
        return res.back().second;
    }

    std::vector<long long> dual;

private:
    std::vector<int> _edge_to;
    std::vector<int> _edge_rev;
    std::vector<long long> _edge_cap;
    std::vector<long long> _edge_cost;
    std::vector<long long> _edge_flow;
    std::vector<int> _edge_to_rev;
public:
    std::vector<long long> duals;  // Instead of encapsulating separately, define as needed.
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long INF = 1000000000LL;

    int n; cin >> n;
    int a1, a2, a3; cin >> a1 >> a2 >> a3;
    int b1, b2, b3; cin >> b1 >> b2 >> b3;

    mcf_graph_int_cost g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);
    for (int i = 1; i <= 3; i++) {
        for (int j = 4; j <= 6; j++) {
            int cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, INF, cost);
        }
    }

    long long f, ans1;
    {
        auto res = g.slope(0, 7);
        f = res.back().first; 
        ans1 = res.back().second;
    }

    long long ans2 = min((long long)a1, (long long)b2) +
                     min((long long)a2, (long long)b3) +
                     min((long long)a3, (long long)b1);

    cout << ans1 << ' ' << ans2 << "\n";

    return 0;
}

