    int rock1 = vals1[0], sci1 = vals1[1], paper1 = vals1[2];
    int rock2 = vals2[0], sci2 = vals2[1], paper2 = vals2[2];

    auto maximum = [&]() {
        int ans = 0;
        ans += min(rock1, sci2);
        ans += min(sci1, paper2);
        ans += min(paper1, rock2);
        return ans;
    };

    auto match = [](int a, int b) -> int {
        if (a == b) return 0;
        if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) return 1;
        return -1;
    };

    auto give = [&](vector<vector<int>>& l1, vector<vector<int>>& l2) -> int {
        int ans = 0;
        int curr1_num = 0, curr2_num = 0;
        int curr1_type = 0, curr2_type = 0;
        // using vectors as stacks
        while (!l1.empty() || !l2.empty()) {
            if (curr1_num == 0 && !l1.empty()) {
                auto v = l1.back(); l1.pop_back();
                curr1_num = v[0]; curr1_type = v[1];
            }
            if (curr2_num == 0 && !l2.empty()) {
                auto v = l2.back(); l2.pop_back();
                curr2_num = v[0]; curr2_type = v[1];
            }
            if (curr1_num == 0 || curr2_num == 0) {
                continue;
            }
            int min_count = min(curr1_num, curr2_num);
            int s = max(0, min_count * match(curr1_type, curr2_type));
            ans += s;

            if (curr1_num < curr2_num) {
                curr2_num -= curr1_num;
                curr1_num = 0;
            } else if (curr1_num > curr2_num) {
                curr1_num -= curr2_num;
                curr2_num = 0;
            } else {
                curr1_num = 0;
                curr2_num = 0;
            }
        }
        return ans;
    };

    auto minimum = [&]() {
        int ans = INT_MAX;

        vector<vector<int>> l1, l2;
        vector<vector<int>> base = {
            {rock1, 1}, {sci1, 2}, {ppr, 3}
        };
        // Generate all permutations of the first player's moves
        do {
            l1.clear();
            for (auto &p : base)
                l1.push_back(p);
            vector<vector<int>> m1 = l1;
            do {
                l2.clear();
                for (auto &p : base)
                    l2.push_back(p);
                vector<vector<int>> m2 = l2;
                int res = give(m1, m2);
                if (res < ans) ans = res;
            } while (next_permutation(l2.begin(), l2.end(), [](vector<int>& a, vector<int>& b) {
                return a[1] < b[1];
            }));
        } while (next_permutation(l1.begin(), l1.end()));

        return ans;
    };

    int max_score = maximum();
    int min_score = minimum();

    cout << min_score << " " << max_score << "\n";

    return 0;
}

