int main() {
    int n;
    std::cin >> n;

    std::vector<int> inputA(3), inputB(3);
    for (int i = 0; i < 3; ++i) std::cin >> inputA[i];
    for (int i = 0; i < 3; ++i) std::cin >> inputB[i];

    std::vector<int> inputA2 = inputA;
    std::vector<int> inputB2 = inputB;

    auto getWonMaxFast = [](std::vector<int> inputA, std::vector<int> inputB) {
        int wins = 0;
        for (int i = 0; i < 3; ++i) {
            int good = (i + 1) % 3;
            int win = std::min(inputA[i], inputB[good]);
            inputA[i] -= win;
            inputB[good] -= win;
            wins += win;
        }
        return wins;
    };

    auto getLostMaxFast = [](const std::vector<int>& inputA, const std::vector<int>& inputB) {
        std::vector<std::pair<int, int>> waysToLose = {{0,2}, {1,0}, {2,1}, {0,0}, {1,1}, {2,2}};
        std::vector<std::vector<std::pair<int,int>>> allPermutations;

        // Generate all permutations of waysToLose
        std::vector<int> indices(waysToLose.size());
        for (int i = 0; i < (int)waysToLose.size(); ++i) indices[i] = i;
        do {
            std::vector<std::pair<int,int>> permutation;
            for (int i = 0; i < (int)waysToLose.size(); ++i)
                permutation.push_back(waysToLose[indices[i]]);
            allPermutations.push_back(permutation);
        } while (std::next_permutation(indices.begin(), indices.end()));

        int maxLost = 0;

        for (const auto& permutation : allPermutations) {
            std::vector<int> inputACopy = inputA;
            std::vector<int> inputBCopy = inputB;
            std::vector<int> losts(3, 0);

            for (const auto& wayToLose : permutation) {
                int lost_add = std::min(inputACopy[wayToLose.first], inputBCopy[wayToLose.second]);
                inputACopy[wayToLose.first] -= lost_add;
                inputBCopy[wayToLose.second] -= lost_add;
                losts[wayToLose.first] += lost_add;
            }

            int lostSum = std::accumulate(losts.begin(), losts.end(), 0);
            if (lostSum > maxLost) {
                maxLost = lostSum;
            }
        }

        return maxLost;
    };

    int maxLost = getLostMaxFast(inputA2, inputB2);
    int wins = getWonMaxFast(inputA, inputB);

    std::cout << (n - maxLost) << " " << wins << std::endl;

    return 0;
}

