int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    function<int()> INT = [](){ int x; cin >> x; return x; };
    auto LIST = [&](int N = -1) {
        vector<int> res;
        if (N == -1) {
            int n; cin >> n;
            for (int i = 0; i < n; ++i) res.push_back(INT());
        } else {
            for (int i = 0; i < N; ++i) res.push_back(INT());
        }
        return res;
    };

    int N = INT();
    int M = 3;
    vector<int> A = LIST(M);
    vector<int> B = LIST(M);
    int ans1 = 0;
    for (int i = 0; i < M; ++i) {
        ans1 += min(A[i], B[(i + 1) % M]);
    }

    struct Dinic {
        static const long long INF = 1000000000000000000LL;
        int n;
        std::vector<std::vector<std::array<long long, 3>>> links;
        std::vector<int> depth, progress;

        Dinic(int n_) : n(n_), links(n_), depth(n_), progress(n_) {}

        void add_edge(int from, int to, long long cap) {
            links[from].push_back({cap, to, (long long)links[to].size()});
            links[to].push_back({0, from, (long long)links[from].size() - 1});
        }

        void bfs(int s) {
            std::fill(depth.begin(), depth.end(), -1);
            depth[s] = 0;
            std::queue<int> q;
            q.push(s);
            while (!q.empty()) {
                int v = q.front(); q.pop();
                for (auto &w : links[v]) {
                    long long cap = w[0];
                    int to = (int)w[1];
                    if (cap > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        q.push(to);
                    }
                }
            }
        }

        long long dfs(int v, int t, long long flow) {
            if (v == t) return flow;
            for (int &i = progress[v]; i < (int)links[v].size(); ++i) {
                auto &link = links[v][i];
                long long cap = link[0], to = (int)link[1], rev = (int)link[2];
                if (cap == 0 || depth[v] >= depth[to]) continue;
                long long d = dfs(to, t, std::min(flow, cap));
                if (d > 0) {
                    link[0] -= d;
                    links[to][rev][0] += d;
                    return d;
                }
            }
            return 0;
        }

        long long flow(int s, int t) {
            long long total = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) break;
                std::fill(progress.begin(), progress.end(), 0);
                long long f;
                while ((f = dfs(s, t, INF)) > 0) {
                    total += f;
                }
            }
            return total;
        }

        std::vector<std::tuple<int,int,long long,long long>> get_edges(const std::vector<std::pair<int,int>> &pos) {
            std::vector<std::tuple<int,int,long long,long long>> res;
            for (int i = 0; i < (int)pos.size(); ++i) {
                auto &p = pos[i];
                auto &e = links[p.first][p.second];
                auto &re = links[e[1]][e[2]];
                res.emplace_back(p.first, e[1], e[0] + re[0], re[0]);
            }
            return res;
        }
    };

    vector<std::pair<int,int>> pos;
    int s = 2 * M, t = 2 * M + 1;
    Dinic dinic(2 * M + 2);
    for (int i = 0; i < M; ++i) {
        // s to Alice
        dinic.add_edge(s, i, N);
