#include <bits/stdc++.h>
using namespace std;

vector<long long> primes;

void generate_primes() {
    for (int p = 2; p < 6000; ++p) {
        bool is_prime = true;
        for (auto p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(p);
        }
    }
}

unordered_map<long long, int> factor(long long n) {
    unordered_map<long long, int> d;
    for (auto p : primes) {
        if (p * p > n) break;
        if (n % p == 0) {
            int c = 0;
            while (n % p == 0) {
                n /= p;
                c++;
            }
            d[p] = c;
        }
    }
    if (n > 1) {
        d[n] = 1;
    }
    return d;
}

vector<long long> factors(long long n) {
    auto d = factor(n);
    vector<long long> answer = {1};
    for (auto &p_c : d) {
        long long p = p_c.first;
        int c = p_c.second;
        vector<long long> a2;
        for (auto x : answer) {
            for (int i = 0; i <= c; ++i) {
                long long val = x;
                for (int j = 0; j < i; ++j) val *= p;
                a2.push_back(val);
            }
        }
        answer = a2;
    }
    return answer;
}

long long process(int n, int m) {
    vector<long long> f_dict(n + 1);
    f_dict[0] = 0;
    if (n >= 1) f_dict[1] = 1;
    if (n >= 2) f_dict[2] = 2;
    for (int i = 3; i <= n; ++i) {
        long long val = 2 * f_dict[i - 1];
        for (auto x : factors(i)) {
            if (x >= 2 && x <= i) {
                long long term = f_dict[i / x] - f_dict[(i - 1) / x];
                val += term;
            }
        }
        val %= m;
        f_dict[i] = val;
    }
    return f_dict[n];
}

