// Helper function for modular exponentiation
long long pow(long long base, long long exp, long long mod) {
    long long result = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * cur) % mod;
        cur = (cur * cur) % mod;
        exp >>= 1;
    }
    return result;
}

