bool is_good(const vector<int>& f, int p, int k) {
    for(int i = 0; i < p; i++) {
        if(f[(k * i) % p] != (k * f[i]) % p) {
            return false;
        }
    }
    return true;
}

int gen(vector<int>& f, int p, int k, int i) {
    if(i == p) {
        return is_good(f, p, k) ? 1 : 0;
    } else {
        int ans = 0;
        for(int j = 0; j < p; j++) {
            f.push_back(j);
            ans += gen(f, p, k, i + 1);
            f.pop_back();
        }
