using namespace std;

int invnum(const std::vector<int>& seq) {
    int N = (int)seq.size();
    int res = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = i+1; j < N; ++j) {
            if (seq[i] > seq[j]) {
                ++res;
            }
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Initialize memoization structure: vector of size n+1, each with 2 maps for flag false(0) and true(1)
    std::vector<std::vector<std::unordered_map<int, int>>> memo(n + 1, std::vector<std::unordered_map<int, int>>{});
    for (int i = 0; i <= n; ++i) {
        // Each element has 2 maps: index 0 for flag=false, 1 for flag=true
        // Initialize accordingly
        memo[i].resize(2);
    }

    // Define recursive function as lambda with capture
    std::function<int(int,int,bool)> solve = [&](int N, int k, bool flag) -> int {
        int f = flag ? 1 : 0;
        if (memo[N][f].count(k)) {
            return memo[N][f][k];
        }

        int res;
        if (N == 1) {
            res = -1;
            if (flag) {
                res = 0;
            } else {
                if (k < 0) {
                    res = 1;
                } else {
                    res = 0;
                }
            }
            memo[N][f][k] = res;
            return res;
        }

        int invnum_INF = (N * (N - 1)) / 2;
        if (k < -invnum_INF - 1) {
            res = solve(N, -invnum_INF - 1, flag);
            memo[N][f][k] = res;
            return res;
        }

        if (k >= invnum_INF) {
            memo[N][f][k] = 0;
            return 0;
        }

        res = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) {
                continue;
            }
            int wt = std::min(N - delta, delta + N);
            int sub_flag = (delta == 0) ? 1 : 0;
            // For the recursive call, pass the combined flag (logical AND)
            res += (int)((long long)solve(N - 1, k - delta, (delta == 0) && flag) * wt % mod);
            res %= mod;
        }
        memo[N][f][k] = res;
        return res;
    };

    int ans = solve(n, 0, true) % mod;
    std::cout << ans << "\n";

    return 0;
}

