            ans = (long long)(m + 1) * last_ans % mod;
            long long tp = 0;
            for (int i = 0; i < m; ++i) {
                tp += record[inv ^ 1][i];
                record[inv][i] = tp % mod;
            }
            for (int i = m; i <= tp_size / 2; ++i) {
                tp += record[inv ^ 1][i];
                tp -= record[inv ^ 1][i - m];
                record[inv][i] = tp % mod;
            }
            for (int i = 0; i <= tp_size / 2; ++i) {
                record[inv][tp_size - i] = record[inv][i];
