#include <unordered_map>
#include <utility>

int cal(int n, int m) {
    if (n < m) std::swap(n, m);
    if (m == 1) {
        static std::unordered_map<int, int> dt = {
            {0, 0},
            {1, 1},
            {2, 2},
            {3, 3},
            {4, 2},
            {5, 1}
        };
        return dt[n % 6];
    }
    if (n == 7) {
        if (m == 2) return 2;
        return (n * m) % 2;
    } else if (n >= 4) {
        return (n * m) % 2;
    } else {
        static std::unordered_map<std::pair<int, int>, int, 
            std::hash<int>, 
            bool(*)(const std::pair<int,int>&, const std::pair<int,int>&)> dt(
                4, 
                [](const std::pair<int,int> &a, const std::pair<int,int> &b) {
                    return a.first == b.first && a.second == b.second;
                }
            );
        // Initialize static map with pairs
        static bool initialized = false;
        if (!initialized) {
            dt[{3,2}] = 2;
            dt[{3,1}] = 3;
            dt[{2,2}] = 4;
            dt[{2,1}] = 2;
            initialized = true;
        }
        auto key = std::make_pair(n, m);
        auto it = dt.find(key);
        if (it != dt.end()) return it->second;
        else return (n * m) % 2;
    }
}

