#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, h;
    cin >> n >> h;

    vector<vector<int>> dp(n + 1, vector<int>(n + 1, -1));

    // Function to fill initial values
    auto fill = [&](int i, int j) {
        if (i == 0 && j == 0)
            return 1;
        if (i == 0 || j == 0)
            return 0;
        return -1;
    };

    // Initialize dp with fill values
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            dp[i][j] = fill(i, j);
        }
    }

    // Implement recursive function with memoization
    function<int(int, int)> t = [&](int n, int h) -> int {
        if (dp[n][h] != -1)
            return dp[n][h];
        int sum_value = 0;
        for (int m = 1; m <= n; ++m) {
            int left1 = t(m - 1, h - 1); // t(m-1,h-1)
            int sum1 = 0;
            for (int i = 0; i < h; ++i) {
                sum1 += t(n - m, i);
            }
            int left2 = t(n - m, h - 1); // t(n-m,h-1)
            int sum2 = 0;
            for (int i = 0; i < h - 1; ++i) {
                sum2 += t(m - 1, i);
            }
            sum_value += left1 * sum1 + left2 * sum2;
        }
        dp[n][h] = sum_value;
        return sum_value;
    };

    // Precompute all t(i,j)
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            t(i, j);
        }
    }

    int result = 0;
    for (int i = h; i <= n; ++i)
        result += dp[n][i];

    cout << result << "\n";

    return 0;
}

