            r += num2(i, h - 1) * num2(n - 1 - i, h - 1);
        }
        tab2[key] = r;
    }
    return tab2[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    cout << num1(n) - num2(n, h) << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;
    vector<long long> t(n + 1, 1), s(n + 1, 1);
    for (int m = 1; m <= n; ++m) {
        long long sum_s = 0;
        for (int k = 0; k < m; ++k) {
            sum_s += s[m - 1 - k] * s[k];
        }
        s[m] = sum_s;
    }
    for (int j = 0; j < h; ++j) {
        vector<long long> new_t(n + 1, 0);
        for (int m = 0; m <= n; ++m) {
            long long sum_result = 0;
            for (int k = 0; k <= m; ++k) {
                sum_result += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
            }
            new_t[m] = sum_result;
        }
        t = new_t;
    }
    cout << t[n] << endl;
    return 0;
}
